{"content":"import sys
import json
import re
from collections import Counter


def tokenize(text):
    """Tokens are ASCII letter runs that may contain a single internal apostrophe."""
    # Words like "don't" or "didn't", also "'quoted'" -> quoted
    token_pattern = re.compile(r"[a-zA-Z]+'(?:[a-zA-Z0-9])+|[a-zA-Z]+")
    return token_pattern.findall(text)


def main():
    args = sys.argv[1:]

    file_path = None
    top = 10
    min_length = 1
    ignore_words = set()

    if not args or len(args) == 1:
        try:
            with open("-", mode="rt") as f:
                text = f.read()
        except FileNotFoundError:
            print("Error: file - must read from stdin", file=sys.stderr)
            return

    if len(args) >= 2 and not args[0].startswith("--"):
        file_path = args[1]

    for i in range(len(args)):
        arg = args[i]
        if arg == "--top":
            try:
                top = int(args[i + 1])
            except (ValueError, IndexError):
                continue
            elif len(args) > i + 2:

                del args[i + 1 : i + 2]
        elif arg == "--min-length":
            try:
                min_length = int(args[i + 1])
            except (ValueError, IndexError):
                continue
        elif arg == "--ignore":
            if len(args) > i + 1 and not args[i+1].startswith("-"):
                for word in args[i + 2 :]:
                    ignore_words.add(word.lower())

    text = ""
    if file_path:
        try:
            with open(file_path, mode="rt") as f:
                text = f.read()
        except FileNotFoundError:
            print("Error: file not found", file=sys.stderr)
            return

    words = tokenize(text)
    counts = Counter(w.lower() for w in words if len(w) >= min_length and w not in ignore_words)
    result = [{"word": word, "count": count} for word, count in counts.most_common()]
    # ties sorted by alphabetical (ascending on word when counts equal)
    result.sort(key=lambda x: (-x["count"], x["word"]))

    print(json.dumps([r for r in result[:top]], indent=2))


if __name__ == "__main__":
    main()
